async function loadEmployees(){if(me?.cargo!=='admin')return;const tb=$('employeesTable');tb.innerHTML='<tr><td colspan="6">Carregando funcionários...</td></tr>';try{const data=await callAdmin('listar');employees=data.usuarios||[];tb.innerHTML=employees.length?employees.map(u=>`<tr><td>${esc(u.nome)}</td><td>${esc(u.email)}</td><td>${esc(u.cargo==='admin'?'ADM':'Usuário')}</td><td>${u.ativo?'Ativo':'Inativo'}</td><td>${u.precisa_trocar_senha?'Troca pendente':'Definida'}</td><td><button class="button-secondary" data-reset-employee="${esc(u.id)}" ${u.id===me.id?'disabled title="Não é possível redefinir a própria conta"':''}>Resetar senha</button></td></tr>`).join(''):'<tr><td colspan="6">Nenhum funcionário encontrado.</td></tr>'}catch(e){tb.innerHTML=`<tr><td colspan="6">${esc(e.message)}. Publique a Edge Function gerenciar-funcionarios no Supabase de TESTES.</td></tr>`}}
function resetEmployeeDialog(id){if(me?.cargo!=='admin')return;const u=employees.find(x=>x.id===id);if(!u||id===me.id)return;modal('Redefinir senha temporária',`Funcionário: ${u.nome} · ${u.email}`,`<p>O funcionário deverá trocar a senha no próximo acesso. Informe a senha temporária por um canal privado.</p><form id="resetEmployeeForm" class="form-grid"><label class="full">Nova senha temporária (12 caracteres ou mais)<input name="senha" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label><div class="form-actions"><button class="primary">Confirmar redefinição</button></div></form><div class="feedback" id="modalFeedback"></div>`);$('resetEmployeeForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await callAdmin('resetar',{user_id:id,nova_senha:new FormData(e.target).get('senha')});closeModal();$('employeeFeedback').textContent='Senha temporária redefinida. Informe a nova senha ao funcionário de forma privada.';await loadEmployees()}catch(err){modalAlert(err.message,true);button.disabled=false}}}
